{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '바로잡힌다'는 게 구체적으로 어떤 결과인지 물었을 때, 내담자가 '공정하게 평가받아야 한다'는 표현을 반복하는 것은 '나는 특별한 사람이므로 보통 사람들에게 적용되는 규칙과 대우가 나에게 그대로 적용되어서는 안 된다'는 핵심 신념과 직결됨. 어린 시절 어머니가 '너는 다른 애들과 급이 다르다'며 규칙을 무마해 준 경험이 이 신념의 기원."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/0"],
      "relevance": "상담사가 만족할 수 있는 구체적 결과를 묻는 것은, 내담자가 이 상황을 '바로잡아야'만 하는 이유—즉 보통 사람과 같은 취급을 받는 것이 '그저 그런 사람으로 전락'하는 것을 의미하기 때문—과 연결됨. 상황 사례 0에서 인사팀 통보 직후 임원에게 연락해 뒤집으려 한 행동이 이 가설의 직접적 표현."
    },
    {
      "trait_id": "/coping_strategies/2",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '실적을 만들어 낸 사람과 아무 결과도 없는 사람이 같은 기준으로 평가되는 건가요'라고 말하는 것은, 규정이 자신의 방식과 부딪힐 때 실적을 방패로 삼는 대처 전략과 일치. 상황 사례 1에서 신입 직원의 규정 지적에 '실적 내고 나서 얘기해'라고 면박을 준 패턴과 동일."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": [],
      "relevance": "상담사가 구체적 결과를 묻는 것은 내담자가 통제할 수 없는 평가 자리를 형식적으로 대하는 패턴과 관련됨. 내담자는 처음부터 '절차대로 하는 거 아닌가요'로 이 자리를 규정하며, 구체적 요구를 명확히 하는 질문 자체를 압박으로 느끼는 경향이 이 대처 전략과 맞닿음."
    }
  ]
}

